use std::collections::HashMap;
use verus::prelude::*;

/// two_sum(nums, target) returns the lexicographically smallest pair of
/// distinct indices (i, j) with i < j and nums[i] + nums[j] == target,
/// if such a pair exists without overflow in the subtraction target - nums[i].
/// Otherwise it returns None.
#[verifier(external_body)]
#[requires(true)]
#[ensures(
  // If we return None, then for every 0 ≤ i < j < nums.len(),
  // either target.checked_sub(nums[i]) overflowed (so we skip that i),
  // or else the complement b = target - nums[i] is not found at any j>i.
  match &result {
    None => forall(|i: usize, j: usize| 
      i < j && j < nums.len() ==>
        match target.checked_sub(nums[i]) {
          Some(b) => nums[j] != b,
          None    => true
        }
    ),

    // If we return Some((i, j)), then
    //   1) i < j < nums.len()
    //   2) no overflow occurred: nums[i] + nums[j] = target
    //   3) the pair is lexicographically smallest among all valid pairs.
    Some((i, j)) => 
      i < j && j < nums.len() &&
      // correctness of addition
      nums[i].checked_add(nums[j]) == Some(target) &&
      // lexicographic minimality: for any other (i2<j2) that is valid,
      // (i, j) ≤ (i2, j2).
      forall(|i2: usize, j2: usize| 
        i2 < j2 && j2 < nums.len() &&
        match target.checked_sub(nums[i2]) {
          Some(b2) => nums[j2] == b2,
          None     => false
        } ==>
          (i < i2) || (i == i2 && j <= j2)
      )
  }
)]
fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let mut map: HashMap<i32, Vec<usize>> = HashMap::new();
    // Build a map from value to all its indices
    for (i, &v) in nums.iter().enumerate() {
        map.entry(v).or_default().push(i);
    }
    // Sort each index list so we can binary‐search for the smallest j > i
    for indices in map.values_mut() {
        indices.sort_unstable();
    }

    let n = nums.len();
    for i in 0..n {
        let a = nums[i];
        // compute the needed complement, skipping if subtraction would overflow
        if let Some(b) = target.checked_sub(a) {
            if let Some(indices) = map.get(&b) {
                let key = i + 1;
                // find the first index >= key, which ensures j > i
                match indices.binary_search(&key) {
                    Ok(pos) | Err(pos) if pos < indices.len() => {
                        return Some((i, indices[pos]));
                    }
                    _ => {}
                }
            }
        }
    }

    None
}

